package main

import (
	"bytes"
	"encoding/base64"
	"strings"
	"testing"
)

// Independent AES-128-GCM vector generated by Node's crypto implementation,
// using the same nonce/ciphertext/tag layout as the Hyper client.
const txtVector = "AAECAwQFBgcICQoLgBKV3OnfGGdC9EUAaTiJA78Ndy9yi/kkkDNX5WeBLhTrJfrvZDDA1W/JzEpU48YGnh6n"

func TestOpenTXT(t *testing.T) {
	var out, stderr bytes.Buffer
	if code := run([]string{"open-txt"}, strings.NewReader(txtVector), &out, &stderr); code != 0 {
		t.Fatalf("exit %d: %s", code, stderr.String())
	}
	if got := out.String(); got != "v=1|api-one.example|api-two.example" {
		t.Fatalf("unexpected plaintext %q", got)
	}
	tampered := mustDecode(t, txtVector)
	tampered[len(tampered)-1] ^= 1
	for _, record := range []string{
		"", "v=1|api-one.example", "%%%", base64.StdEncoding.EncodeToString(tampered),
		base64.StdEncoding.EncodeToString(make([]byte, 28)),
		"AAECAwQFBgcICQoLgBKW3OnfGGdC9EUAaTiJA78Nd4PWSzO46p5WUC4uuyoyEa4=", // v=2
		"AAECAwQFBgcICQoLl1/NjefBFGRI4kFDfCyNtJ+vwY/LQEgjkzMTc9krLQ==",     // no version
	} {
		out.Reset()
		if code := run([]string{"open-txt"}, strings.NewReader(record), &out, &stderr); code == 0 || out.Len() != 0 {
			t.Errorf("invalid record returned exit %d and %d plaintext bytes", code, out.Len())
		}
	}
	out.Reset()
	if code := run([]string{"open-txt"}, strings.NewReader(strings.Repeat("A", 16385)), &out, &stderr); code != exitDecode || out.Len() != 0 {
		t.Errorf("oversized record: exit %d, plaintext %d", code, out.Len())
	}
}
